INSERT INTO `mod_forever_journal_lore` (`ID`, `Zone`, `Kind`, `SortOrder`, `Faction`, `Races`, `Classes`, `Era`, `Title`, `Body`, `Sources`) VALUES
(394000, 394, 0, 1, 0, 0, 0, 0, 'Grizzly Hills', 'Low green foothills laced with pine, craggy mountains and picturesque rivers. Countless millennia ago the bear gods Ursoc and Ursol roamed these hills as cubs before they grew into Wild Gods, and Ursoc ruled here with his children, Orsonn and Kodian. It is the ancestral home of the furbolgs.\n\nTo the Alliance and the Horde it was an untamed, forgotten frontier, known to human trappers who keep their own trading posts and a goblin Venture Company busy cutting down the forest.', 'warcraft.wiki.gg: Grizzly Hills (introduction, History, Geography)'),
(394001, 394, 1, 1, 0, 0, 0, 0, 'Grizzlemaw', 'The furbolg city, built in the stump of a fallen World Tree. Its Redfang and Frostpaw tribes are mad and constantly at war. Ursoc''s children, the ancients Orsonn and Kodian, are all but prisoners of their own people at the shrines nearby: the furbolgs will not let them leave, and they love them too much to fight their way out.', 'warcraft.wiki.gg: Grizzlemaw; warcraft.wiki.gg: Rage Fang Shrine; warcraft.wiki.gg: Heart''s Blood Shrine'),
(394002, 394, 1, 2, 0, 0, 0, 0, 'Vordrassil', 'Some 4,500 years before the First War, Fandral Staghelm cut branches from Nordrassil and planted them where saronite had begun to spread. The largest he planted here, over a great saronite deposit, and named it Andrassil, "Crown of the Snow". Malfurion and the Circle were furious, but for decades the tree towered over Northrend and all seemed well.\n\nThen the taunka and the forest nymphs, peaceful peoples both, fell on each other with vile barbarity. The druids found that the tree''s roots had reached down to the prison of an Old God, and its taint was driving everything near it mad. They cut it down and renamed it Vordrassil, the "Broken Crown". The roots are still there.', 'warcraft.wiki.gg: Vordrassil (introduction, History)'),
(394003, 394, 1, 3, 0, 0, 0, 0, 'Amberpine Lodge', 'A meeting hall built by Alliance woodsmen long before the war, now commandeered by the Valiance Expedition.', 'warcraft.wiki.gg: Amberpine Lodge'),
(394004, 394, 1, 4, 0, 0, 0, 0, 'The Westfall Brigade', 'The People''s Militia of Westfall has come north to fight the Scourge under its old captain, Gryan Stoutmantle, renamed the Westfall Brigade, and built its camp here.', 'warcraft.wiki.gg: Westfall Brigade Encampment'),
(394005, 394, 1, 5, 0, 0, 0, 0, 'Conquest Hold', 'The Horde''s stronghold, its walls built around a deep fighting pit, ruled by Conqueror Krenna, an orc aggressive and ill-tempered even by the Horde''s measure.', 'warcraft.wiki.gg: Conquest Hold'),
(394006, 394, 1, 6, 0, 0, 0, 0, 'Camp Oneqwah', 'The taunka camp of Tormak the Scarred, where taunka from villages across Northrend plan to take refuge.', 'warcraft.wiki.gg: Camp Oneqwah'),
(394007, 394, 1, 7, 0, 0, 0, 0, 'The Trappers', 'The human trappers of the hills are an independent people who live in palisaded villages like Silverbrook and Solstice and trade from their own posts. Many of them have joined something called the Wolfcult.', 'warcraft.wiki.gg: Grizzly Hills (introduction); warcraft.wiki.gg: Silverbrook'),
(394008, 394, 1, 8, 0, 0, 0, 0, 'Bloodmoon Isle', 'The Lich King found Archmage Arugal''s work with the worgen of Silverpine, and raised him from his death in Shadowfang Keep to serve the Scourge. His shade leads the Wolfcult from a new Shadowfang Tower on this island, slowly turning the trappers into worgen. The miners of Hollowstone refused him; he made them all undead.', 'warcraft.wiki.gg: Shadowfang Tower; warcraft.wiki.gg: Bloodmoon Isle; warcraft.wiki.gg: Hollowstone Mine'),
(394009, 394, 1, 9, 0, 0, 0, 0, 'Thor Modan', 'The ancient home of the iron dwarves, built much like Ironforge, down to a statue like that of Modimus Anvilmar. Thousands of years ago the stone giants, long at war with the iron dwarves, tore the land open and brought much of the city down. The dwarves are rebuilding it with grim determination, while the giants batter it with boulders and whole trees. The iron dwarves now rule from Dun Argol.', 'warcraft.wiki.gg: Thor Modan; warcraft.wiki.gg: Dun Argol; warcraft.wiki.gg: Boulder Hills'),
(394010, 394, 1, 10, 0, 0, 0, 0, 'The Drakkari Ruins', 'The Drakkari ice trolls once ruled the north of the hills. Drakil''jin was a burial ground for their people and their ancient kings, its walls decorated with piles of skulls. Drak''Tharon Keep, their great fortress on the border of Zul''Drak, is now held by the Scourge.', 'warcraft.wiki.gg: Drakil''jin Ruins; warcraft.wiki.gg: Drak''Tharon Keep'),
(394011, 394, 1, 11, 0, 0, 0, 0, 'Venture Bay and the Logging Camps', 'The Venture Company came here to clear-cut the forest. The Horde and Alliance drove it off, and now fight each other for its camps and its bay.', 'warcraft.wiki.gg: Blue Sky Logging Grounds; warcraft.wiki.gg: Blackriver Logging Camp'),
(394012, 394, 1, 12, 0, 0, 0, 0, 'Ashwood Lake', 'A legend says that a maiden of these hills guarded a powerful blade, and to keep anyone from wielding it she was cursed into the shape of a frog. She lives among the frogs of the lake still. A kiss, they say, would break the curse.', 'warcraft.wiki.gg: Ashwood Lake'),
(394030, 394, 2, 1, 0, 0, 0, 0, 'Ursoc', 'The bear god, who once ruled these hills. He was reborn among the furbolgs, horribly twisted by the taint beneath Vordrassil.', 'warcraft.wiki.gg: Grizzly Hills (History, Notable characters)');
